"use strict";
const exercises=[{"id":"roman-sidebend","name":"45° sehpada yana eğilme","group":"Karın","primary":"İç ve dış oblik kaslar","secondary":"Belin yan tarafındaki quadratus lumborum","equipment":"Hiperekstansiyon sehpası","cue":"Kalçanın yan tarafını pede yasla ve ayaklarını sabitle. Gövdeni öne döndürmeden yana eğil, ardından bacaklarınla aynı hizaya dön."},{"id":"atlas-42","name":"Bench press","group":"Göğüs","cue":"Barı göğsüne kontrollü indir ve yukarı it.","primary":"Büyük göğüs kası","secondary":"Arka kol, ön omuz","equipment":"Sehpa + Barbell","artist":"Everkinetic"},{"id":"atlas-87","name":"Barfiks","group":"Sırt","cue":"Dirseklerini aşağı çekerek gövdeni bara yaklaştır.","primary":"Geniş sırt kası","secondary":"Pazı","equipment":"Bar","artist":"Everkinetic"},{"id":"atlas-122","name":"Barbell squat","group":"Bacak","cue":"Barı sırtında sabit tutarak diz ve kalçadan çömelip doğrul.","primary":"Ön uyluk","secondary":"Arka uyluk","equipment":"Barbell","artist":"Everkinetic"},{"id":"atlas-6","name":"Arnold press","group":"Omuz","cue":"Avuçların sana bakarken başla. Dambılları yukarı iterken avuçlarını öne çevir.","primary":"Omuz kası","secondary":"Arka kol","equipment":"Dambıl","artist":"Everkinetic"},{"id":"atlas-99","name":"Barbell deadlift","group":"Kalça","cue":"Barı vücuduna yakın tutarak diz ve kalçanı birlikte aç.","primary":"Büyük kalça kası ve ön uyluk","secondary":"Arka uyluk ve sırt ekstansörleri","equipment":"Barbell","artist":"Everkinetic"},{"id":"atlas-48","name":"Cable crossover","group":"Göğüs","cue":"Dirsek açını koruyarak iki kabloyu göğsünün önünde birleştir.","primary":"Büyük göğüs kası","secondary":"Omuz kası","equipment":"Kablo","artist":"Everkinetic"},{"id":"atlas-25","name":"Oturarak kablo çekiş","group":"Sırt","cue":"Gövdeni sabit tut. Tutacağı alt kaburgalarına doğru çek.","primary":"Geniş sırt kası","secondary":"Pazı, omurga ekstansörleri","equipment":"Kablo","artist":"Everkinetic"},{"id":"atlas-293","name":"Eğimli sehpada çapraz mekik","group":"Karın","cue":"Gövdeni kaldırırken bir omzunu karşı dize doğru yaklaştır.","primary":"Oblikler ve düz karın kası","secondary":"Kalça fleksörleri","equipment":"Negatif eğimli sehpa","artist":"Everkinetic"},{"id":"atlas-103","name":"Sehpada sırt ekstansiyonu","group":"Sırt","cue":"Kalça ekleminden öne eğil. Gövden bacaklarınla aynı hizaya gelene kadar yüksel.","primary":"Sırt ekstansörleri ve büyük kalça kası","secondary":"Arka uyluk","equipment":"Hiperekstansiyon sehpası","artist":"Everkinetic"},{"id":"atlas-29","name":"T-bar row","group":"Sırt","cue":"Gövde açını koruyarak tutacağı alt göğsüne çek.","primary":"Geniş sırt kası","secondary":"Pazı, omuz kası","equipment":"T-bar","artist":"Everkinetic"},{"id":"atlas-43","name":"Eğimli barbell bench press","group":"Göğüs","cue":"Eğimli sehpada barı üst göğsüne indir ve tekrar yukarı it.","primary":"Büyük göğüs kası","secondary":"Arka kol","equipment":"Eğimli sehpa + Barbell","artist":"Everkinetic"},{"id":"atlas-47","name":"Pec deck","group":"Göğüs","cue":"Dirseklerini omuz hizasının altında tutarak pedleri önünde birleştir.","primary":"Büyük göğüs kası","secondary":"Harekete göre gövde stabilizatörleri","equipment":"Pec deck","artist":"Everkinetic"},{"id":"atlas-54","name":"Paralel barda göğüs dipsi","group":"Göğüs","cue":"Gövdeni hafif öne eğip dirseklerini bük. Kollarından destek alarak yüksel.","primary":"Büyük göğüs kası","secondary":"Arka kol, omuz kası","equipment":"Vücut ağırlığı + Paralel bar","artist":"Everkinetic"},{"id":"atlas-55","name":"Dambıl bench press","group":"Göğüs","cue":"Dambılları göğüs hizasına indir ve yukarı it.","primary":"Büyük göğüs kası","secondary":"Omuz kası, arka kol","equipment":"Dambıl + Sehpa","artist":"Everkinetic"},{"id":"atlas-56","name":"Dambıl fly","group":"Göğüs","cue":"Hafif bükülü kollarını iki yana aç. Dambılları geniş bir yay çizerek birleştir.","primary":"Büyük göğüs kası","secondary":"Omuz kası, arka kol","equipment":"Sehpa + Dambıl","artist":"Everkinetic"},{"id":"atlas-75","name":"Ayaklar yüksekte şınav","group":"Göğüs","cue":"Ayaklarını sabit bir sehpaya koy. Gövdeni düz tutarak şınav çek.","primary":"Büyük göğüs kası, omuz kası","secondary":"Arka kol","equipment":"Vücut ağırlığı + Sehpa","artist":"Everkinetic"},{"id":"atlas-86","name":"Ters kürek çekiş","group":"Sırt","cue":"Sabit barın altından göğsünü bara doğru çek. Kalçanı gövdenle aynı hizada tut.","primary":"Geniş sırt, orta trapez ve romboidler","secondary":"Pazı ve arka omuz","equipment":"Sabit bar","artist":"Everkinetic"},{"id":"atlas-89","name":"Ters tutuş barfiks","group":"Sırt","cue":"Avuçların kendine dönükken dirseklerini aşağı çekerek yüksel.","primary":"Geniş sırt kası","secondary":"Pazı","equipment":"Vücut ağırlığı + Bar","artist":"Everkinetic"},{"id":"atlas-92","name":"Düz kolla kablo çekiş","group":"Sırt","cue":"Dirsek açını koruyarak üst makara tutacağını uyluklarına doğru indir.","primary":"Geniş sırt kası","secondary":"Arka kol","equipment":"Kablo","artist":"Everkinetic"},{"id":"atlas-118","name":"Barbell Romen deadlift","group":"Kalça","cue":"Dizlerini hafif kır. Barı bacaklarına yakın tutarak kalçanı geriye gönder ve doğrul.","primary":"Arka uyluk","secondary":"Baldır, soleus, ön uyluk, büyük kalça kası","equipment":"Barbell","artist":"Everkinetic"},{"id":"atlas-117","name":"Yatarak leg curl","group":"Bacak","cue":"Kalçanı pede bastırarak topuklarını kendine doğru çek.","primary":"Arka uyluk","secondary":"Harekete göre gövde stabilizatörleri","equipment":"Makine","artist":"Everkinetic"},{"id":"atlas-123","name":"Hack squat makinesi","group":"Bacak","cue":"Sırtını pede dayayarak çömel. Ayaklarınla platformu it.","primary":"Ön uyluk","secondary":"Arka uyluk, baldır, soleus","equipment":"Makine","artist":"Everkinetic"},{"id":"atlas-127","name":"Leg press","group":"Bacak","cue":"Belini destekten ayırmadan dizlerini bük. Platformu kontrollü biçimde it.","primary":"Ön uyluk","secondary":"Baldır, soleus, arka uyluk","equipment":"Makine","artist":"Everkinetic"},{"id":"atlas-137","name":"Dambılla basamağa çıkış","group":"Kalça","cue":"Bir ayağını platforma yerleştir. Üstteki ayağından kuvvet alarak yüksel.","primary":"Ön uyluk ve büyük kalça kası","secondary":"Arka uyluk ve baldır","equipment":"Dambıl + Platform","artist":"Everkinetic"},{"id":"atlas-138","name":"Front squat","group":"Bacak","cue":"Barı ön omuzlarında tut. Dirseklerini düşürmeden çömelip kalk.","primary":"Ön uyluk","secondary":"Arka uyluk, baldır, soleus","equipment":"Barbell","artist":"Everkinetic"},{"id":"atlas-142","name":"Makinede diz açma","group":"Bacak","cue":"Diz eklemini makinenin ekseniyle hizala. Pedi kaldır ve yavaşça indir.","primary":"Ön uyluk","secondary":"Harekete göre gövde stabilizatörleri","equipment":"Makine","artist":"Everkinetic"},{"id":"atlas-156","name":"Makinede kalça açış","group":"Kalça","cue":"Gövdeni sabit tutarak dizlerini iki yana aç.","primary":"Orta ve küçük kalça kasları","secondary":"Tensor fascia lata","equipment":"Makine","artist":"Everkinetic"},{"id":"atlas-157","name":"Makinede kalça kapatış","group":"Bacak","cue":"Dizlerini pedlere bastırarak kontrollü biçimde birbirine yaklaştır.","primary":"İç uyluk kasları","secondary":"Karın","equipment":"Makine","artist":"Everkinetic"},{"id":"atlas-151","name":"Baş üstü squat","group":"Bacak","cue":"Barı başının üzerinde dengede tutarak kontrollü çömel ve doğrul.","primary":"Ön uyluk","secondary":"Büyük kalça kası, baldır, soleus, arka uyluk, omuz kası, omurga ekstansörleri","equipment":"Barbell","artist":"Everkinetic"},{"id":"atlas-161","name":"Zercher squat","group":"Bacak","cue":"Barı dirsek kıvrımlarında sabitle. Gövdeni dik tutarak çömelip kalk.","primary":"Ön uyluk","secondary":"Büyük kalça kası, arka uyluk, baldır, soleus","equipment":"Barbell","artist":"Everkinetic"},{"id":"atlas-206","name":"Halatla triseps itiş","group":"Kol","cue":"Dirseklerin yanında sabitken halatı aşağı it. Altta uçları hafifçe ayır.","primary":"Arka kol","secondary":"Harekete göre gövde stabilizatörleri","equipment":"Kablo","artist":"Everkinetic"},{"id":"atlas-211","name":"Barbell curl","group":"Kol","cue":"Barı dirseklerini bükerek kaldır. Gövdeni sallamadan indir.","primary":"Pazı","secondary":"Omuz kası, ön kol","equipment":"Barbell","artist":"Everkinetic"},{"id":"atlas-220","name":"Konsantrasyon curl","group":"Kol","cue":"Üst kolunu uyluğuna yasla. Dambılı kaldırıp kontrollü indir.","primary":"Pazı","secondary":"Ön kol","equipment":"Dambıl","artist":"Everkinetic"},{"id":"atlas-227","name":"Hammer curl","group":"Kol","cue":"Avuçların birbirine bakarken dambılları dirsekten bükerek kaldır.","primary":"Pazı","secondary":"Harekete göre gövde stabilizatörleri","equipment":"Dambıl","artist":"Everkinetic"},{"id":"atlas-239","name":"Scott sehpasında barbell curl","group":"Kol","cue":"Üst kollarını pede yerleştir. Barı dirsekten bükerek kaldır.","primary":"Pazı","secondary":"Ön kol","equipment":"Barbell","artist":"Everkinetic"},{"id":"atlas-192","name":"Çift dambılla triseps kickback","group":"Kol","cue":"Oturup gövdeni öne eğ. Üst kollarını sabit tutarak iki dirseğini geriye doğru aç.","primary":"Arka kol","secondary":"Arka omuz","equipment":"Dambıl + Sehpa","artist":"Everkinetic"},{"id":"atlas-49","name":"Dar tutuş bench press","group":"Kol","cue":"Barı omuz genişliğine yakın tut. Dirseklerini gövdene yakın tutarak pres yap.","primary":"Arka kol ve büyük göğüs kası","secondary":"Ön omuz","equipment":"Barbell + Sehpa","artist":"Everkinetic"},{"id":"atlas-20","name":"Bantla ters açış","group":"Omuz","cue":"Bandı önünde tutarak kollarını iki yana aç. Omuzlarını yukarı çekme.","primary":"Omuz kası","secondary":"Arka kol, geniş sırt kası","equipment":"Direnç bandı","artist":"Everkinetic"},{"id":"atlas-14","name":"Barbell dikey çekiş","group":"Omuz","cue":"Barı gövdene yakın tutarak rahat bir yüksekliğe çek ve indir.","primary":"Omuz kası","secondary":"Pazı, üst sırt","equipment":"Barbell","artist":"Everkinetic"},{"id":"atlas-112","name":"Kabloda kalça itişi","group":"Kalça","cue":"Ayak bileği kayışını geriye it. Belini sabit tut.","primary":"Büyük kalça kası","secondary":"Arka uyluk","equipment":"Kablo","artist":"Everkinetic"},{"id":"atlas-119","name":"Oturarak leg curl","group":"Bacak","cue":"Uyluklarını pede sabitle. Dizlerini bükerek alt pedi geriye çek.","primary":"Arka uyluk","secondary":"Harekete göre gövde stabilizatörleri","equipment":"Makine","artist":"Everkinetic"},{"id":"atlas-129","name":"Dambılla geri hamle","group":"Bacak","cue":"Dambılları yanında tut. Bir adım geriye atıp öndeki ayağından kuvvet alarak kalk.","primary":"Ön uyluk","secondary":"Baldır, soleus, arka uyluk, büyük kalça kası, kalça abdüktörleri","equipment":"Dambıl","artist":"Everkinetic"},{"id":"atlas-134","name":"Barla basamağa çıkış","group":"Kalça","cue":"Bar sırtındayken sabit platforma bir ayakla basıp yüksel.","primary":"Ön uyluk ve büyük kalça kası","secondary":"Arka uyluk ve baldır","equipment":"Barbell + Platform","artist":"Everkinetic"},{"id":"atlas-273","name":"Leg press makinesinde baldır itişi","group":"Bacak","cue":"Ön ayaklarınla platformu iterek topuklarını yükseltip indir.","primary":"Baldır, soleus","secondary":"Harekete göre gövde stabilizatörleri","equipment":"Makine","artist":"Everkinetic"},{"id":"atlas-284","name":"Bisiklet mekik","group":"Karın","cue":"Bir bacağını uzatırken karşı omzunu bükülü dizine doğru döndür.","primary":"Düz karın kası","secondary":"Harekete göre gövde stabilizatörleri","equipment":"Vücut ağırlığı","artist":"Everkinetic"},{"id":"atlas-286","name":"Diz üstü bar rollout","group":"Karın","cue":"Dizlerinden destek alarak barı ileri yuvarla. Gövdeni sabit tutarak geri çek.","primary":"Düz karın kası","secondary":"Omurga ekstansörleri, omuz kası","equipment":"Barbell","artist":"Everkinetic"},{"id":"atlas-288","name":"Oturarak kablolu mekik","group":"Karın","cue":"Halatı sabit tutarak kaburgalarını leğen kemiğine yaklaştır.","primary":"Düz karın kası","secondary":"Harekete göre gövde stabilizatörleri","equipment":"Kablo","artist":"Everkinetic"},{"id":"atlas-294","name":"Dambılla yana eğilme","group":"Karın","cue":"Dambılı tek yanında tut. Gövdeni yana eğip kontrollü biçimde dik konuma getir.","primary":"Oblikler ve quadratus lumborum","secondary":"Sırt ekstansörleri","equipment":"Dambıl","artist":"Everkinetic"},{"id":"atlas-296","name":"Pilates topunda diz çekme","group":"Karın","cue":"Bacakların topun üzerindeyken dizlerini gövdende topla ve tekrar uzat.","primary":"Karın kasları ve kalça fleksörleri","secondary":"Omuz ve ön uyluk","equipment":"Pilates topu","artist":"Everkinetic"},{"id":"push","name":"Şınav","group":"Göğüs","primary":"Büyük göğüs kası","secondary":"Arka kol ve ön omuz","equipment":"Vücut ağırlığı","cue":"Gövdeni düz tutarak dirseklerini bük. Zemini iterek başlangıca dön.","artist":"Everkinetic"},{"id":"curl","name":"Pazı bükme","group":"Kol","primary":"Pazı ve brakiyalis","secondary":"Ön kol","equipment":"Dambıl","cue":"Üst kolunu gövdenin yanında tut. Dirseğini bükerek dambılı kaldır ve yavaşça indir.","artist":"Everkinetic"},{"id":"raise","name":"Yana açış","group":"Omuz","primary":"Orta omuz","secondary":"Üst trapez ve supraspinatus","equipment":"Dambıl","cue":"Dirseğini hafif bükülü tutarak kolunu yana doğru omuz hizasına kaldır ve indir.","artist":"Everkinetic"},{"id":"kick","name":"Triseps kickback","group":"Kol","primary":"Arka kol","secondary":"Arka omuz","equipment":"Dambıl","cue":"Öne eğil ve üst kolunu gövdenle aynı hizada tut. Dirseğini açıp tekrar bük.","artist":"Everkinetic"},{"id":"crunch","name":"Kısa mekik","group":"Karın","primary":"Düz karın kası","secondary":"Oblikler","equipment":"Mat","cue":"Sırtüstü yat ve alt bacaklarını bir desteğe yerleştir. Boynunu çekmeden kürek kemiklerini yerden kaldır.","artist":"Everkinetic"},{"id":"front","name":"Öne kaldırış","group":"Omuz","primary":"Ön omuz","secondary":"Üst göğüs","equipment":"Dambıl","cue":"Dambılı uyluğun önünden omuz hizasına kaldır. Gövdeni sallamadan indir.","artist":"Everkinetic"},{"id":"seatedcurl","name":"Oturarak pazı bükme","group":"Kol","primary":"Pazı ve brakiyalis","secondary":"Ön kol","equipment":"Dambıl","cue":"Sehpada dik otur. Dirseğini gövdenin yanında tutarak dambılı kaldır.","artist":"Everkinetic"},{"id":"shrug","name":"Dambılla omuz silkme","group":"Sırt","primary":"Üst trapez","secondary":"Ön kol","equipment":"Dambıl","cue":"Kollarını düz tut. Omuzlarını kulaklarına doğru kaldır ve indir.","artist":"Everkinetic"},{"id":"seatedpress","name":"Oturarak omuz presi","group":"Omuz","primary":"Ön ve orta omuz","secondary":"Arka kol","equipment":"Dambıl","cue":"Dik otur. Dambılı omuz hizasından başının üzerine it ve geri indir.","artist":"Everkinetic"},{"id":"squat","name":"Squat","group":"Bacak","primary":"Ön uyluk, büyük kalça kası","secondary":"Karın ve iç uyluk","equipment":"Vücut ağırlığı","cue":"Kalçanı geriye ve aşağıya indir. Ayağının tamamıyla yere bastırarak doğrul."},{"id":"row","name":"Dambıl row","group":"Sırt","primary":"Geniş sırt kası","secondary":"Pazı, arka omuz ve orta sırt","equipment":"Dambıl","cue":"Kalçadan öne eğil. Dambılı kalçana doğru çekip kontrollü indir."},{"id":"press","name":"Omuz presi","group":"Omuz","primary":"Ön ve orta omuz","secondary":"Arka kol","equipment":"Dambıl","cue":"Dambılı omuz hizasından yukarı it. Kontrollü biçimde başlangıca dön."},{"id":"bridge","name":"Kalça köprüsü","group":"Kalça","primary":"Büyük kalça kası","secondary":"Arka uyluk ve karın","equipment":"Mat","cue":"Sırtüstü yatıp dizlerini bük. Ayaklarınla yere bastırarak kalçanı kaldır ve indir."},{"id":"calf","name":"Topuk yükseltme","group":"Bacak","primary":"Baldır kasları","secondary":"Ayak bileği çevresi","equipment":"Vücut ağırlığı","cue":"Ayak önünden yükselerek topuklarını kaldır. Kısa bir duraklamayla aşağı in."},{"id":"goblet","name":"Goblet squat","group":"Bacak","primary":"Ön uyluk ve büyük kalça kası","secondary":"Karın ve iç uyluk","equipment":"Dambıl","cue":"Dambılı göğsünde tut. Dizlerini bükerek çömel ve doğrul."},{"id":"box","name":"Sehpaya squat","group":"Bacak","primary":"Ön uyluk ve büyük kalça kası","secondary":"Karın","equipment":"Sabit sehpa","cue":"Kalçanı arkadaki sabit sehpaya kontrollü indir. Ayaklarınla zemini iterek kalk."},{"id":"split","name":"Split squat","group":"Bacak","primary":"Ön uyluk ve büyük kalça kası","secondary":"Arka uyluk","equipment":"Vücut ağırlığı","cue":"Ayakların adım pozisyonundayken iki dizini bük. Öndeki ayaktan kuvvet alarak yüksel."},{"id":"splitdb","name":"Dambıllı split squat","group":"Bacak","primary":"Ön uyluk ve büyük kalça kası","secondary":"Karın","equipment":"Dambıl","cue":"Dambılı yanında tut. Adım pozisyonunu koruyarak aşağı in ve kalk."},{"id":"backlunge","name":"Geri hamle","group":"Kalça","primary":"Büyük kalça ve ön uyluk","secondary":"İç uyluk","equipment":"Vücut ağırlığı","cue":"Bir ayağınla geriye adım at ve iki dizini bük. Öndeki ayaktan destek alıp geri gel."},{"id":"rdl","name":"Romen deadlift","group":"Kalça","primary":"Arka uyluk ve büyük kalça kası","secondary":"Sırt ekstansörleri","equipment":"Dambıl","cue":"Dizlerini hafif kır. Dambılı bacağına yakın tutarak kalçanı geriye gönder ve doğrul."},{"id":"morning","name":"Good morning","group":"Kalça","primary":"Arka uyluk ve büyük kalça kası","secondary":"Sırt ekstansörleri","equipment":"Vücut ağırlığı","cue":"Ellerini göğsünde tut. Sırtının biçimini koruyarak kalçadan öne eğil."},{"id":"legext","name":"Oturarak diz açma","group":"Bacak","primary":"Ön uyluk","secondary":"Kalça fleksörleri","equipment":"Sabit sehpa","cue":"Sehpaya otur. Bir dizini açarak alt bacağını kaldırıp kontrollü indir."},{"id":"seatcalf","name":"Oturarak topuk yükseltme","group":"Bacak","primary":"Soleus","secondary":"Gastroknemius","equipment":"Sabit sehpa","cue":"Ayak önünü yerde tut. Otururken topuğunu yükselt ve tekrar indir."},{"id":"kneepush","name":"Diz üstü şınav","group":"Göğüs","primary":"Büyük göğüs kası","secondary":"Arka kol ve ön omuz","equipment":"Mat","cue":"Dizlerin yerdeyken omuzdan dize düz bir çizgi kur. Dirseklerini büküp zemini it."},{"id":"incline","name":"Eğimli şınav","group":"Göğüs","primary":"Büyük göğüs kası","secondary":"Arka kol ve ön omuz","equipment":"Sabit sehpa","cue":"Ellerini sabit bir sehpaya yerleştir. Göğsünü sehpaya yaklaştır ve geri it."},{"id":"floorpress","name":"Yerde dambıl pres","group":"Göğüs","primary":"Büyük göğüs kası","secondary":"Arka kol ve ön omuz","equipment":"Dambıl","cue":"Sırtüstü yat. Üst kolun yere yaklaştığı konumdan dambılı yukarı it."},{"id":"pullover","name":"Dambıl pullover","group":"Sırt","primary":"Geniş sırt ve büyük göğüs kası","secondary":"Arka kol","equipment":"Dambıl","cue":"Sırtüstü yatıp dambılı göğsünün üzerinde tut. Dirsek açını koruyarak başının gerisine indir ve geri getir."},{"id":"skull","name":"Yatarak triseps açış","group":"Kol","primary":"Arka kol","secondary":"Ön kol","equipment":"Dambıl","cue":"Dambılı omzunun üstünde tut. Üst kolunu sabit tutarak dirseğini bük ve aç."},{"id":"overhead","name":"Baş üstü triseps açış","group":"Kol","primary":"Arka kol","secondary":"Karın","equipment":"Dambıl","cue":"Üst kolunu kulağının yanında tut. Dambılı başının arkasına indirip dirseğini aç."},{"id":"proneY","name":"Yüzüstü Y kaldırışı","group":"Sırt","primary":"Alt trapez","secondary":"Arka omuz","equipment":"Mat","cue":"Yüzüstü uzan. Kolların Y biçimindeyken ellerini zeminden hafifçe kaldır."},{"id":"singlebridge","name":"Tek bacak kalça köprüsü","group":"Kalça","primary":"Büyük kalça kası","secondary":"Arka uyluk ve karın","equipment":"Mat","cue":"Bir ayağını kaldır. Yerdeki topuğundan destek alarak kalçanı yükselt."},{"id":"bridgewalk","name":"Köprüde diz kaldırma","group":"Kalça","primary":"Büyük kalça kası","secondary":"Karın ve kalça fleksörleri","equipment":"Mat","cue":"Köprü pozisyonunda kalçanı sabit tutarak bir dizini kendine çek ve ayağını indir."},{"id":"donkey","name":"Diz bükülü kalça itişi","group":"Kalça","primary":"Büyük kalça kası","secondary":"Arka uyluk ve karın","equipment":"Mat","cue":"Dört ayak üzerinde bir dizini bükülü tut. Ayağını tavana doğru kaldır."},{"id":"bird","name":"Bird dog","group":"Karın","primary":"Sırt ekstansörleri ve karın","secondary":"Kalça ve omuz","equipment":"Mat","cue":"Dört ayak konumundan karşı kol ve bacağını uzat. Gövdeni sabit tutarak geri dön."},{"id":"mount","name":"Dağ tırmanışı","group":"Karın","primary":"Kalça fleksörleri ve karın","secondary":"Omuz ve ön uyluk","equipment":"Mat","cue":"Yüksek plank konumunda sırayla dizlerini göğsüne doğru çek."},{"id":"legraise","name":"Yatarak bacak kaldırma","group":"Karın","primary":"Kalça fleksörleri","secondary":"Karın","equipment":"Mat","cue":"Sırtüstü yat. Gövdeni sabit tutabildiğin aralıkta bacaklarını kaldırıp indir."},{"id":"heel","name":"Sırtüstü topuk dokundurma","group":"Karın","primary":"Karın ve kalça fleksörleri","secondary":"Oblikler","equipment":"Mat","cue":"Sırtüstü yatıp dizlerini bükerek kaldır. Bir topuğunu yere dokundurup başlangıca dön."},{"id":"hipflex","name":"Ayakta diz çekme","group":"Bacak","primary":"Kalça fleksörleri","secondary":"Karın","equipment":"Vücut ağırlığı","cue":"Dik durarak bir dizini kalça hizasına çek. Ayağını kontrollü indir."},{"id":"wallpush","name":"Duvar şınavı","group":"Göğüs","primary":"Büyük göğüs kası","secondary":"Arka kol ve ön omuz","equipment":"Duvar","cue":"Ellerini duvara yerleştir. Dirseklerini bükerek yaklaş ve duvarı it."},{"id":"curlleg","name":"Ayakta diz bükme","group":"Bacak","primary":"Arka uyluk","secondary":"Baldır","equipment":"Vücut ağırlığı","cue":"Dizlerini yan yana tutup bir topuğunu kalçana yaklaştır ve indir."},{"id":"hipback","name":"Ayakta kalça ekstansiyonu","group":"Kalça","primary":"Büyük kalça kası","secondary":"Arka uyluk","equipment":"Vücut ağırlığı","cue":"Gövdeni dik tut. Bir bacağını belinden yaylanmadan geriye uzat."}];
